from gurobipy import *

def solve_problem():
    m = Model("Battlefield_Logistics")
    m.setParam("TimeLimit", 100)  # Set time limit to 100 seconds

    # Data
    depots = list(range(8))  # D0..D7
    units = list(range(9))  # U0..U8
    supplies = list(range(3))  # S0..S2
    days = list(range(1))  # Day0..Day0

    demands = [[[42.12], [29.08], [25.19]], [[49.66], [20.55], [22.89]], [[49.08], [45.91], [36.4]], [[26.01], [43.96], [12.42]], [[49.56], [33.22], [35.42]], [[30.68], [21.62], [46.76]], [[46.09], [28.4], [18.71]], [[32.35], [32.77], [41.1]], [[10.86], [12.54], [46.61]]]
    depot_supplies = [[[40.57], [34.81], [35.29]], [[51.29], [29.92], [35.83]], [[36.18], [38.15], [41.05]], [[59.1], [45.88], [37.85]], [[54.89], [34.07], [46.28]], [[47.23], [47.94], [34.49]], [[61.28], [47.63], [29.72]], [[50.43], [38.44], [34.4]]]
    transport_costs = [[4.1, 3.5, 4.27, 3.21, 3.36, 4.4, 1.49, 2.6, 3.3], [2.57, 4.47, 1.19, 2.85, 2.23, 4.7, 3.43, 2.41, 1.54], [1.49, 1.78, 2.18, 4.06, 3.95, 3.06, 3.09, 3.48, 1.77], [1.34, 1.89, 2.14, 2.83, 4.79, 1.7, 2.77, 1.77, 3.08], [4.85, 2.48, 4.28, 4.95, 1.25, 2.06, 3.92, 3.93, 4.16], [2.27, 2.68, 1.78, 3.17, 2.9, 3.04, 4.08, 4.62, 2.52], [2.61, 3.19, 1.49, 1.4, 4.98, 3.8, 1.44, 1.95, 3.7], [1.49, 4.79, 3.48, 3.08, 4.01, 4.46, 1.53, 4.19, 1.2]]
    risk_costs = [[107.92, 174.35, 192.3, 69.99, 192.0, 97.84, 70.53, 153.26, 167.54], [123.3, 167.57, 191.35, 159.11, 101.25, 158.81, 98.0, 89.27, 121.22], [110.75, 162.17, 130.09, 194.89, 195.01, 110.9, 176.45, 153.2, 82.67], [144.69, 89.64, 51.73, 158.64, 187.46, 181.45, 84.28, 68.06, 61.07], [90.49, 144.52, 99.08, 121.66, 57.42, 52.84, 155.05, 106.73, 73.12], [133.69, 151.16, 68.92, 96.56, 164.52, 192.04, 70.18, 70.05, 182.69], [79.57, 144.03, 73.97, 174.97, 71.85, 111.01, 105.2, 192.11, 183.43], [148.19, 100.28, 151.31, 115.31, 98.84, 148.22, 120.0, 87.01, 165.5]]
    supply_volumes = [1.74, 1.78, 0.54]
    penalty_costs = [93.07, 74.05, 61.97]
    vehicle_cost = 10.0
    vehicle_capacity = 73.0
    total_vehicles = 11

    # Decision variables
    # Flow_D{d}_U{u}_S{s}_Day{t}: Amount of supply s from depot d to unit u on day t
    flows = {}
    for t in days:
        for d in depots:
            for u in units:
                for s in supplies:
                    flows[(d, u, s, t)] = m.addVar(lb=0.0, vtype=GRB.CONTINUOUS, name=f"Flow_D{d}_U{u}_S{s}_Day{t}")

    # Slack_U{u}_S{s}_Day{t}: Shortage of supply s at unit u on day t
    slacks = {}
    for t in days:
        for u in units:
            for s in supplies:
                slacks[(u, s, t)] = m.addVar(lb=0.0, vtype=GRB.CONTINUOUS, name=f"Slack_U{u}_S{s}_Day{t}")

    # Veh_D{d}_U{u}_Day{t}: Number of vehicles on route d->u on day t
    vehicles = {}
    for t in days:
        for d in depots:
            for u in units:
                vehicles[(d, u, t)] = m.addVar(lb=0.0, vtype=GRB.INTEGER, name=f"Veh_D{d}_U{u}_Day{t}")

    # Route_D{d}_U{u}_Day{t}: Route d->u is active on day t (binary)
    routes = {}
    for t in days:
        for d in depots:
            for u in units:
                routes[(d, u, t)] = m.addVar(vtype=GRB.BINARY, name=f"Route_D{d}_U{u}_Day{t}")

    # Objective: Minimize total cost (transport + penalty + vehicle + risk)
    obj = quicksum(
        transport_costs[d][u] * flows[(d, u, s, t)]
        for t in days for d in depots for u in units for s in supplies
    )
    obj += quicksum(
        penalty_costs[s] * slacks[(u, s, t)]
        for t in days for u in units for s in supplies
    )
    obj += quicksum(
        vehicle_cost * vehicles[(d, u, t)]
        for t in days for d in depots for u in units
    )
    obj += quicksum(
        risk_costs[d][u] * routes[(d, u, t)]
        for t in days for d in depots for u in units
    )
    m.setObjective(obj, GRB.MINIMIZE)

    # Depot capacity constraints: Total outflow <= supply
    for t in days:
        for d in depots:
            for s in supplies:
                m.addConstr(
                    quicksum(flows[(d, u, s, t)] for u in units) <= depot_supplies[d][s][t],
                    name=f"DepotCap_D{d}_S{s}_Day{t}"
                )

    # Demand constraints: Inflow + slack >= demand
    for t in days:
        for u in units:
            for s in supplies:
                m.addConstr(
                    quicksum(flows[(d, u, s, t)] for d in depots) + slacks[(u, s, t)] >= demands[u][s][t],
                    name=f"Demand_U{u}_S{s}_Day{t}"
                )

    # Vehicle capacity constraints: Total volume <= vehicles * capacity
    for t in days:
        for d in depots:
            for u in units:
                m.addConstr(
                    quicksum(supply_volumes[s] * flows[(d, u, s, t)] for s in supplies) <= vehicle_capacity * vehicles[(d, u, t)],
                    name=f"VehCap_D{d}_U{u}_Day{t}"
                )

    # Route activation constraints: vehicles <= total_vehicles * route
    for t in days:
        for d in depots:
            for u in units:
                m.addConstr(
                    vehicles[(d, u, t)] <= total_vehicles * routes[(d, u, t)],
                    name=f"RouteAct_D{d}_U{u}_Day{t}"
                )

    # Fleet size constraints: Total vehicles <= total_vehicles
    for t in days:
        m.addConstr(
            quicksum(vehicles[(d, u, t)] for d in depots for u in units) <= total_vehicles,
            name=f"FleetSize_Day{t}"
        )

    m.optimize()
    return m
